    public boolean checkAbstract(IMember member) throws JavaModelException {
        int modifiers = member.getFlags();
        // Should not match Modifier.isAbstract, as it's a different FQN
        if (Modifier.isAbstract(modifiers) && confirmAbstract(member)) {
            return true;
        }

        // Should not match if the argument is not a method call member.getFlags()
        if (org.eclipse.jdt.core.Flags.isAbstract(1024) && confirmAbstract(member)) {
